CREATE TABLE IF NOT EXISTS board_meetings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, meeting_type text NOT NULL DEFAULT 'Board Meeting', meeting_date date NOT NULL, notice_status text NOT NULL DEFAULT 'Pending', agenda_status text NOT NULL DEFAULT 'Draft', minutes_status text NOT NULL DEFAULT 'Pending', chair_name text, company_secretary text, quorum_status text NOT NULL DEFAULT 'Pending', action_status text NOT NULL DEFAULT 'Open', notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS board_resolutions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid REFERENCES board_meetings(id) ON DELETE SET NULL, entity_name text NOT NULL, resolution_ref text NOT NULL, title text NOT NULL, resolution_type text NOT NULL DEFAULT 'Ordinary', status text NOT NULL DEFAULT 'Draft', approval_date date, effective_date date, responsible_role text, implementation_status text NOT NULL DEFAULT 'Open', reserved_matter boolean NOT NULL DEFAULT false, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS statutory_registers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), entity_name text NOT NULL, register_type text NOT NULL, jurisdiction text NOT NULL, status text NOT NULL DEFAULT 'Needs Review', last_reviewed date, next_review_date date, responsible_role text, evidence_reference text, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO board_meetings(entity_name,meeting_type,meeting_date,notice_status,agenda_status,minutes_status,quorum_status,action_status,notes) SELECT 'OSANVAULT AFRICA LTD','Constitutional Governance Setup',CURRENT_DATE,'Pending','Draft','Pending','Pending','Open','Initial institutional governance setup; populate only after board/secretary confirms applicable corporate records and meeting requirements.' WHERE NOT EXISTS (SELECT 1 FROM board_meetings WHERE entity_name='OSANVAULT AFRICA LTD' AND meeting_type='Constitutional Governance Setup');
INSERT INTO statutory_registers(entity_name,register_type,jurisdiction,status,responsible_role,notes) SELECT 'OSANVAULT AFRICA LTD','Corporate statutory registers','Nigeria','Needs Review','Company Secretary','Validate applicable registers against current CAC/CAMA requirements before marking complete.' WHERE NOT EXISTS (SELECT 1 FROM statutory_registers WHERE entity_name='OSANVAULT AFRICA LTD' AND register_type='Corporate statutory registers');